TARGET_ANSWERS = 'ABCDBCDACB'

def make(i, row):
    tag, prompt, opts, answer, reason = row
    target = TARGET_ANSWERS[i - 1]
    correct_index = opts.index(answer)
    distractors = [text for index, text in enumerate(opts) if index != correct_index]
    position = ord(target) - 65
    arranged = distractors[:position] + [answer] + distractors[position:]
    options = [{'id': chr(65+j), 'text': text} for j, text in enumerate(arranged)]
    aid = target
    steps = [f'讀題定位：圈出「{tag}」以及波長、頻率、折射率、入射角、光源或光譜資料。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合三稜鏡分光與色散原理。', '排除誘答：分清波長、頻率、速率與偏折角，並檢查光源、介質和量測裝置是否造成替代解釋。', '最後回查：確認實驗條件、資料品質與結論的適用範圍都與題幹相符。']
    return {'id': f'question-science-content-ka-iv-10-{i}', 'subject': 'science', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-science-content-ka-iv-10'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究白光、三稜鏡色散、波長、頻率、光譜、彩虹與分光實驗的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-08', 'lessonId': 'lesson-science-content-ka-iv-10', 'examPatternRefs': [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '三稜鏡分光', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}], 'solutionStrategy': '先辨識白光的多波長組成，再連結折射率對波長的差異，最後以光譜資料與控制變因檢查色散解釋。', 'solutionSteps': steps}

for i, row in enumerate(DATA, 1):
    (OUT / f'question-science-content-ka-iv-10-{i}.json').write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + '\n')
